Here is the commit message:
svcrdma: bound check rq_pages index in inline path

svc_rdma_copy_inline_range indexed rqstp->rq_pages[rc_curpage] without
verifying rc_curpage stays within the allocated page array. Add guards
before the first use and after advancing to a new page.

Fixes: d7cc73972661 ("svcrdma: support multiple Read chunks per RPC")
Cc: stable@vger.kernel.org
Signed-off-by: Joshua Rogers <linux@joshua.hu>
Signed-off-by: Chuck Lever <chuck.lever@oracle.com>

Here is the root cause:
The function `svc_rdma_copy_inline_range` did not validate that `head->rc_curpage` is less than `rqstp->rq_maxpages` before using it as an index into `rqstp->rq_pages`, leading to potential out-of-bounds access.

Here is the patch:
  */
 static int svc_rdma_copy_inline_range(struct svc_rqst *rqstp,
 				      struct svc_rdma_recv_ctxt *head,
 				      unsigned int offset,
 				      unsigned int remaining)
 {
 	unsigned char *dst, *src = head->rc_recv_buf;
 	unsigned int page_no, numpages;

 	numpages = PAGE_ALIGN(head->rc_pageoff + remaining) >> PAGE_SHIFT;
 	for (page_no = 0; page_no < numpages; page_no++) {
 		unsigned int page_len;

+		if (head->rc_curpage >= rqstp->rq_maxpages)
+			return -EINVAL;
+
 		page_len = min_t(unsigned int, remaining,
 				 PAGE_SIZE - head->rc_pageoff);

 		if (!head->rc_pageoff)
 			head->rc_page_count++;

 		dst = page_address(rqstp->rq_pages[head->rc_curpage]);
 		memcpy((unsigned char *)dst + head->rc_pageoff, src + offset, page_len);

 		head->rc_readbytes += page_len;
 		head->rc_pageoff += page_len;
 		if (head->rc_pageoff == PAGE_SIZE) {
 			head->rc_curpage++;
 			head->rc_pageoff = 0;
 		}
 		remaining -= page_len;
 		offset += page_len;
 	}

 	return 0;
 }



